extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var load_count := count_in_code("res://basket.gd", "load")
	check("no_load", load_count == 0, "Non devono esserci chiamate a load() in basket.gd: usa costanti preload()")
	var untyped := untyped_declarations("res://basket.gd")
	check("typed", untyped == 0, "Tutte le variabili e funzioni devono avere tipi statici espliciti")
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve avviarsi senza errori"):
		return
	await wait_frames(2)
	var rocks := find_all_by_class(main, "Sprite2D")
	var rock_count := 0
	for r in rocks:
		if r.get_script() != null and r.get_script().resource_path == "res://rock.gd":
			rock_count += 1
	check("rocks_spawned", rock_count >= 4, "La fila di rocce deve essere generata come prima (almeno 4 rocce)")

